head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil55000n";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil55000n.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_newListInvstgMasterPage.get("total")) + "건 (" + String(dma_newListInvstgMasterPage.get("currentPage")) + "/" + String(dma_newListInvstgMasterPage.get("endListPage")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_newListApfm, tx_fn_openAdjReqWin) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_reload_onclick
 * @description 「일반」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reload_onclick = async function(e){
    try {
        await scwin.reload(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55000n.btn_reload_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55000n.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_newListInvstgMasterPageList_oncellclick
 * @description grd_newListInvstgMasterPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_newListInvstgMasterPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_newListInvstgMasterPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_newListInvstgMasterPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["step1DtlStat"] === '') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; } return; } if (r["step1DtlStat"] === '30') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step1DtlStat"] === '32') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step1DtlStat"] === '33') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step1DtlStat"] === '34') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step1DtlStat"] === '35') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step1DtlStat"] === '36') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step1DtlStat"] === '37') { await scwin.pubofrRslt(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '30') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '32') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '33') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '34') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '35') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '36') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '37') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '30') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '32') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '33') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '34') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '35') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '36') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step3DtlStat"] === '37') { await scwin.newListApplContn(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '30') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '32') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '33') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '34') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '35') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '36') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step4DtlStat"] === '37') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '30') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '32') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '33') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '34') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '35') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '36') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["step5DtlStat"] === '37') { await scwin.newListApfm(r["bzProcsNo"], r["step5DtlStat"], r["isurCd"]); return; }
        if (r["submitPossibleYn"] === 'Y') { await scwin.submit(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '34' || r["step2DtlStat"] === '34' || r["step3DtlStat"] === '34'|| r["step4DtlStat"] === '34'|| r["step5DtlStat"] === '34') { await scwin.openAdjReqPop(r["bzProcsNo"], "140"); return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35' || r["step3DtlStat"] === '35'|| r["step4DtlStat"] === '35'|| r["step5DtlStat"] === '35') { await scwin.submit(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35' || r["step3DtlStat"] === '35' || r["step4DtlStat"] === '35' || r["step5DtlStat"] === '35') { await scwin.submit(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35' || r["step3DtlStat"] === '35' || r["step4DtlStat"] === '35' || r["step5DtlStat"] === '35') { await scwin.openAdjReqPop(r["bzProcsNo"], "140"); return; }
        if (r["recvCompleteYn"] === 'Y') { await scwin.openAdjReqPop(r["bzProcsNo"], "140"); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_newListInvstgMasterPageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_269_onclick
 * @description krxpage_pagenavigator_269 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_269_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_pubofrRsltReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_269.page' }); } await scwin.searchList(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_pubofrRslt
 * @description pubofr Rslt 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_pubofrRslt = async function () {
    const sbmOptions = {
        id: "tx_fn_pubofrRslt",
        method: "post",
        action: "/listInvstg/pubOfrRslt.do",
        ref: "dma_pubofrRsltReq",
        target: "dlt_newListInvstgMasterPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

