 * @name grd_newListInvstgMasterPageList_fillAct
 * @description grd new List Invstg Master Page List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_newListInvstgMasterPageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_newListInvstgMasterPageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["step1DtlStat"] === '') { v = "미작성"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_newListInvstgMasterPageList.fillAct' });
    }
};

